const variantPayloads = [
	{
		id: 'blurred',
		neverRequireSignedURLs: true,
		options: {
			blur: 15,
			fit: 'scale-down',
			height: 360,
			metadata: 'none',
			width: 360,
		},
	},
	{
		id: 'preview',
