];

export const onRequestPost: PagesFunction<{ IMAGES: KVNamespace }> = async ({ request, env }) => {
	let apiToken: string, accountId: string;

	try {
		const setup = (await env.IMAGES.get('setup', 'json')) as Setup;
		apiToken = setup.apiToken;
		accountId = setup.accountId;
	} catch (thrown) {
		return jsonResponse(
			{ error: `Could not get setup configuration: ${thrown}.` },
			{ status: 500 }
		);
	}

	try {
		const keysResponse = await fetch(
			`https://api.cloudflare.com/client/v4/accounts/${accountId}/images/v1/keys`,
			{
				headers: { Authorization: `Bearer ${apiToken}` },
			}
		);
		const {
			result: {
				keys: [{ value: imagesKey }],
			},
		} = await keysResponse.json();

		await env.IMAGES.put('setup', JSON.stringify({ apiToken, accountId, imagesKey }));

		const variantResponsePromises = await Promise.allSettled(
			variantPayloads.map(async variantPayload =>
				fetch(`https://api.cloudflare.com/client/v4/accounts/${accountId}/images/v1/variants`, {
					method: 'POST',
					body: JSON.stringify(variantPayload),
					headers: {
						Authorization: `Bearer ${apiToken}`,
					},
				})
			)
		);

		for (const responsePromise of variantResponsePromises) {
			if (responsePromise.status === 'rejected' || !responsePromise.value.ok) {
				throw new Error('Could not configure a variant.');
			}
		}

		return jsonResponse(true);
	} catch (thrown) {
		return jsonResponse(
			{
				error: `Could not configure Cloudflare Images: ${thrown}.`,
			},
			{ status: 500 }
		);
	}
};

import { jsonResponse } from '../../../utils/jsonResponse';

export const onRequestPost: PagesFunction<{ IMAGES: KVNamespace }> = async ({ request, env }) => {
	let accountId: string;

	try {
		accountId = (await request.json<{ accountId: string }>()).accountId;
	} catch {
		return jsonResponse({ error: 'Could not parse account ID.' }, { status: 400 });
	}

	try {
		const { apiToken } = (await env.IMAGES.get('setup', 'json')) as Setup;
		await env.IMAGES.put('setup', JSON.stringify({ apiToken, accountId }));
		return jsonResponse(true);
	} catch (thrown) {
		return jsonResponse({ error: `Could not select account: ${thrown}` });
	}
};

import createStripeClient from "../createStripeClient";

export async function onRequestPost(context) {
	const { STRIPE_SECRET_KEY, PRICE, HOST } = context.env;
	const stripe = createStripeClient(STRIPE_SECRET_KEY);

	const session = await stripe.checkout.sessions.create({
		mode: "payment",
		line_items: [
			{
				price: PRICE,
				quantity: 1,
			},
		],
		success_url: `${HOST}/api/success?session_id={CHECKOUT_SESSION_ID}`,
		cancel_url: `${HOST}/api/canceled`,
		billing_address_collection: "auto",
	});

	return Response.redirect(session.url, 303);
}

import createStripeClient from "../createStripeClient";

export async function onRequestGet(context) {
	const {
		CLOUDFLARE_ACCOUNT_ID,
		CLOUDFLARE_API_TOKEN,
		CLOUDFLARE_STREAM_VIDEO_UID,
		STRIPE_SECRET_KEY,
		CLOUDFLARE_STREAM_SUBDOMAIN,
		HOST,
	} = context.env;
	const { search } = new URL(context.request.url);
	const params = new URLSearchParams(search);
	const session_id = params.get("session_id");
	const stripe = createStripeClient(STRIPE_SECRET_KEY);
	const session = await stripe.checkout.sessions.retrieve(session_id);
	if (!session) {
		throw new Error("No session found");
	}

	const response = await fetch(
		`https://api.cloudflare.com/client/v4/accounts/${CLOUDFLARE_ACCOUNT_ID}/stream/${CLOUDFLARE_STREAM_VIDEO_UID}/token`,
		{
			method: "POST",
			headers: {
				Authorization: `Bearer ${CLOUDFLARE_API_TOKEN}`,
				"content-type": "application/json;charset=UTF-8",
			},
			body: JSON.stringify({
				exp: Math.floor(Date.now() / 1000) + 12 * 60 * 60,
				downloadable: false,
				accessRules: [
					{ type: "ip.geoip.country", country: ["SM"], action: "block" },
				],
			}),
		}
	);
	const { result } = await response.json();

	const signedUrl = `https://${CLOUDFLARE_STREAM_SUBDOMAIN}.cloudflarestream.com/${result.token}/iframe`;

	return Response.redirect(
		`${HOST}/watch?signedUrl=${signedUrl}&session_id=${session_id}`,
		303
	);
}

